import { existsSync, unlinkSync } from 'node:fs';
import { join } from 'node:path';

/** Relative path (under parentDir) where child-state files live. */
const CHILDREN_REL = join('.claude', 'state', 'children');

/** Resolve the children directory for a given parent worktree root. */
export function childrenDir(parentDir: string): string {
  return join(parentDir, CHILDREN_REL);
}

/** Resolve the path to a specific child's state file. */
function childPath(parentDir: string, sid: string): string {
  return join(childrenDir(parentDir), `${sid}.json`);
}

/** Remove a single child-state file. Silent on missing/permission errors. */
export function deleteChild(parentDir: string, sid: string): void {
  const target = childPath(parentDir, sid);
  try {
    if (existsSync(target)) unlinkSync(target);
  } catch {
    /* ignore */
  }
}
